  "sql": "SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(d.pubmed_id, d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary md JOIN activities act ON md.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid JOIN compound_structures cs ON md.molregno = cs.molregno LEFT JOIN compound_records cr ON act.record_id = cr.record_id LEFT JOIN docs d ON a.doc_id = d.doc_id WHERE act.standard_type = 'IC50' AND act.standard_relation = '=' AND td.pref_name = 'Cytochrome P450 1A2' AND td.organism = 'Homo sapiens' ORDER BY md.chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(d.pubmed_id, d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id, td.pref_name, td.organism"
